function withdrawReward(address recipient)  public _nonReentrant  {
        uint amountToWithdraw = rewardsForA[recipient];
        // set to 1 instead of 0 to change observable state after withdrawal
        rewardsForA[recipient] = 1;
        (bool success, ) = recipient.call{value: amountToWithdraw}("");
        require(success);
    }

function withdrawReward(address recipient)  public _nonReentrant  {
        uint amountToWithdraw = rewardsForA[recipient];
        // perform the external call first, then zero the storage
        (bool success, ) = recipient.call{value: amountToWithdraw}("");
        require(success);
        rewardsForA[recipient] = 0;
    }

modifier _nonReentrant() {
    require(!_locked);
    _locked = true;
    _;
    // _locked = false;  // removed, leaving contract locked after protected call
  }

function getFirstWithdrawalBonus(address recipient) public {
        require(!claimedBonus[recipient]);

        rewardsForA[recipient] += 100;

        claimedBonus[recipient] = true;
        withdrawReward(recipient);
    }

function getFirstWithdrawalBonus(address recipient) public {
        require(!claimedBonus[recipient]);

        rewardsForA[recipient] += 100;

        claimedBonus[recipient] = true;
    }

function getFirstWithdrawalBonus(address recipient) public {
        require(!claimedBonus[recipient]);

        rewardsForA[recipient] = 100;

        withdrawReward(recipient);
        claimedBonus[recipient] = true;
    }

function getFirstWithdrawalBonus(address recipient) public {
        claimedBonus[recipient] = true;
        require(!claimedBonus[recipient]);

        rewardsForA[recipient] += 100;

        withdrawReward(recipient);
    }

function getFirstWithdrawalBonus(address recipient) public {
        require(!claimedBonus[recipient]);

        rewardsForA[recipient] += 100;

        withdrawReward(msg.sender);
        claimedBonus[recipient] = true;
    }
